\label{def:factor basis}
    Let $\Sigma=\{a_1, a_2, \dots, a_n\}$ be an alphabet and let $W\subset \Sigma^+$. Let the set $V\subset\Sigma^+$ satisfy  $|V|\leq |\Sigma|$ and $W\subseteq V^+$. We call such a $V$ a \emph{factor basis of $W$}.\par
    Similarly, given an endomorphism $\varphi:\Sigma^+\rightarrow\Sigma^+$ with $W=\{\varphi(a_i) \mid 1 \leq i \leq n \}$, we call any factor basis $V$ of $W$ a \emph{factor basis of $\varphi$}. We call a factor basis $V$ of $W$ trivial if $V=W$ or $V=\Sigma$. Otherwise, a factor basis is nontrivial.

{\cite{Ner90}}
    Let $\varphi:\Sigma^+\rightarrow\Sigma^+$ be an endomorphism over an alphabet $\Sigma$.
    \begin{itemize}
        \item Determining if there exists a factor basis of $\varphi$ with cardinality no more than $|\Sigma|-1$ is NP-complete.
        \item Determining whether every factor basis of $\varphi$ has cardinality $|\Sigma|$ is co-NP-complete.
    \end{itemize}\par

\label{ex:factor tree 2}
    Let $\varphi:\{a,b,c\}^+\rightarrow\{a,b,c\}+$ be the rank-preserving endomorphism satisfying $\varphi(a)=abbb, \varphi(b)=acba, \varphi(c)=bbba$. Note that $\varphi$ admits exactly the following factor bases:
    \begin{align*}
V_{1} &= \{abbb, acba, bbba\}, & V_{2} &= \{a, acba, bbb\}, & V_{3} &= \{a, acba, b\}, \\
V_{4} &= \{a, acb, bbb\}, & V_{5} &= \{a, bbb, cba\}, & V_{6} &= \{a, acb, b\}, \\
V_{7} &= \{a, b, cba\}, & V_{8} &= \{a, bbb, cb\}, & V_{9} &= \{a, ac, b\}, \\
V_{10} &= \{a, b, cb\}, & V_{11} &= \{a, b, c\}. \\
\end{align*}
Since $|V_i|=|\{a,b,c\}|$ for all $i, 1\leq i \leq 11$, we have shown that $\varphi$ is rank-preserving.
The derivation relationship between these factor bases is shown in Figure \ref{fig:factor tree 2}. \hfill $\Diamond$

\label{prop:derivedVset}
 Let $\varphi:\Sigma^+\rightarrow\Sigma^+$ be an endomorphism for an alphabet $\Sigma=\{a_1, a_2, \dots, a_n\}$,  and let $V=\{v_1, v_2, \dots, v_m\}\subset\Sigma^+$ with $m\leq n$ be a factor basis of $\varphi$. The following statements are equivalent:
        \begin{itemize}
            \item The endomorphism $\psi:\Sigma^+\rightarrow\Sigma^+$ induced by the factor basis $V$ and a surjection $f:\{1, 2, \dots, n\}\rightarrow\{1, 2, \dots m\}$ satisfies the equality $\psi=\iota_2\circ \iota_1$ for non-automorphisms $\iota_1, \iota_2:\Sigma^+\rightarrow\Sigma^+$.
            \item There exists a nontrivial factor basis $V'\subset\Sigma^+$ that is more derived than $V$.
        \end{itemize}

\label{prop: commutative}
    Let $\varphi_1, \varphi_2:\Sigma^+\rightarrow\Sigma^+$ be  endomorphisms for an alphabet $\Sigma=\{a_1, a_2, \dots, a_n\}$. Then $\varphi_1 $ and $ \varphi_2$ commute under composition if there exists a set $S\subseteq \Sigma$ such that:
    \begin{enumerate}[i)]
        \item  for all elements $s\in S,\varphi_1(s)\in S^+$ and $\varphi_2(s)=s$, and
        \item for all elements $r\notin S, \varphi_1(r)=r$ and $\varphi_2(r)\in (\Sigma\setminus S)^+$.
    \end{enumerate}

Let $\varphi:\Sigma^+\rightarrow\Sigma^+$ be an endomorphism for an alphabet $\Sigma=\{a_1, a_2, \dots, a_n\}$ and let $w\in\Sigma^+$ be a word. It then follows that:
\begin{align*}
       (|\varphi(w)|_{a_1}, |\varphi(w)|_{a_2}, \dots, |\varphi(w)|_{a_n})^T=(|w|_{a_1}, |w|_{a_2}, \dots, |w|_{a_n})^TP(\varphi).
\end{align*}

\label{ex:constant times matrix}
    Let $M\in\mathbb{N}^{2\times 2}$ be the incidence matrix that satisfies $M=\big(\begin{smallmatrix}  8 & 4 \\ 10 & 6\end{smallmatrix}\big)$. Note that $M=2\left(\begin{smallmatrix}
        4 & 2 \\ 5 & 3
    \end{smallmatrix}\right)$, and let $\varphi_1, \varphi_2:\Sigma^+\rightarrow\Sigma^+$ be the rank-preserving endomorphisms satisfying $\varphi_1(a)=a^2b^2a^4b^2a^2,  \varphi_1(b)=a^6b^2a^2b^4a^2, \varphi_2(a)=aba^3b^2a^2ba^2$ and $\varphi_2(b)=a^5b^3a^2ba^3b^2$. Note that $P(\varphi_1)=P(\varphi_2)=M$. It can be shown that $\varphi_1$ admits the factor basis $V=\{bb, aa\}$, and $\varphi_2$ does not admit a nontrivial factor basis. Thus, the endomorphism $\varphi_1$ is reducible and $\varphi_2$ is irreducible. \hfill $\Diamond$

\label{prop:matrix transformations}
    Let $P\in\mathbb{N}_0^{n\times n}$ be an incidence matrix that represents exclusively (ir-)reducible rank-preserving endomorphisms. Then the following operations are robust with respect to (ir-)reducibility:
    \begin{enumerate}[i)]
        \item swapping the $i^{\text{th}}$ and $j^{\text{th}}$ rows of the matrix and
        \item swapping the $i^{\text{th}}$ and $j^{\text{th}}$ columns of the matrix.
    \end{enumerate}

\label{prop:exclusively reducible morphisms}
    Let the incidence matrix $P\in\mathbb{N}_0^{2\times 2}$ satisfy one of:
    \begin{enumerate}[i)]
        \item $P=\big(\begin{smallmatrix}
        2 & 2 \\ 2 & 2
    \end{smallmatrix}\big)$, or
    \item $P=\big(\begin{smallmatrix}
         1 & \alpha \\ 1 & \beta
     \end{smallmatrix} \big)$, where $\alpha, \beta >1$ are not coprime.
    \end{enumerate}
    Then $P$ represents exclusively reducible rank-preserving endomorphisms.

\label{prop:1diag}
    Let the incidence matrix $P\in\mathbb{N}_0^{2\times 2}$ satisfy $P=\big(\begin{smallmatrix}
        1 & y \\ z & 1
    \end{smallmatrix}\big)$ for $y,z\in\mathbb{N}_0$ where $y=1$ and $z=0$ (or vice versa) or $y>1$ and $z>1$. Then $P$ represents exclusively irreducible rank-preserving endomorphisms.

Let $P=\big( \begin{smallmatrix}
        2 & 1 \\ 4 & 7\end{smallmatrix}\big)=\left(\begin{smallmatrix}
            1 & 0 \\ 1 & 1
        \end{smallmatrix}\right)\left(\begin{smallmatrix}
            2 & 1 \\ 2 & 6
        \end{smallmatrix}\right)$ be an incidence matrix. Note that $P$ satisfies the second condition of Proposition \ref{prop: gcd or minmax}. Hence, there exists a reducible rank-preserving endomorphism $\varphi:\{a,b\}^+\rightarrow\{a,b\}^+$ such that $P(\varphi)=P$. Indeed, for  $\varphi(a)=a^2b, \varphi(b)=a^2ba^2b^6$ and, for rank-preserving endomorphisms $\psi_1, \psi_2:\{a,b\}^+\rightarrow\{a,b\}^+$ defined as $\psi_1(a)=a, \psi_1(b)=ab, \psi_2(a)=a^2b, \psi_2(b)=aab^6$, we can see that $\varphi=\psi_2\circ \psi_1$. \hfill $\Diamond$
